// back exclusively from the root observation output
// dbg_shared_write_prefetch_ready, never inferred from the flag.  The whole
// combination is validated in the central final check after the parse loop.
static bool write_prefetch_opt = false;    // +write-prefetch=0|1

replacements.new:
// §58 next-WR page prefetch opt-in (test-only driver plumbing).
// +write-prefetch=0|1 (default 0) drives the new root input
// shared_write_prefetch_i in every tick().  The CLI value is only the
// REQUEST: the actual A second-destination-page WRITE recipe success is read
// back exclusively from the root observation output
// dbg_shared_write_prefetch_ready, never inferred from the flag.  The whole
// combination is validated in the central final check after the parse loop,
// which accepts +physical-bypass=2 or 3; mode2 additionally forbids the
// source-sponsor handover (+source-cutover=0) while mode3 accepts
// +source-cutover=0|1.
static bool write_prefetch_opt = false;    // +write-prefetch=0|1

replacements.old:
// §58 next-WR page prefetch: centralised opt-in validation.  It runs after
// every flag has been parsed exactly once, so its outcome never depends on
// the command-line order.  It only constrains the REQUEST; whether the RTL
// really prepared A's second destination-page WRITE recipe is a terminal
// RTL observation (dbg_shared_write_prefetch_ready), never a planned value.

replacements.new:
// §58 next-WR page prefetch: centralised opt-in validation.  It runs after
// every flag has been parsed exactly once, so its outcome never depends on
// the command-line order.  It only constrains the REQUEST; whether the RTL
// really prepared A's second destination-page WRITE recipe is a terminal
// RTL observation (dbg_shared_write_prefetch_ready), never a planned value.
// Accepted physical-bypass values are 2 or 3.  mode2 forbids the
// source-sponsor handover (+source-cutover=0); mode3 accepts it optionally
// (+source-cutover=0|1).  The natural/shared/2048/keepq1/no-pause
// conditions are unchanged.

replacements.old:
if (task_physical_bypass != 2) {
    std::fprintf(stderr,
        "nonblock_actual_dma_test: +write-prefetch=1 requires "
        "+physical-bypass=2 (the mode2 shared-frontier contract)\n");
    return 2;
}

replacements.new:
if (task_physical_bypass != 2 && task_physical_bypass != 3) {
    std::fprintf(stderr,
        "nonblock_actual_dma_test: +write-prefetch=1 requires "
        "+physical-bypass=2|3 (the mode2/mode3 shared-frontier "
        "contract)\n");
    return 2;
}

replacements.old:
if (source_cutover_opt) {
    std::fprintf(stderr,
        "nonblock_actual_dma_test: +write-prefetch=1 requires no "
        "source-sponsor handover (+source-cutover=0)\n");
    return 2;
}

replacements.new:
if (source_cutover_opt && task_physical_bypass == 2) {
    std::fprintf(stderr,
        "nonblock_actual_dma_test: +write-prefetch=1 with "
        "+physical-bypass=2 requires no source-sponsor handover "
        "(+source-cutover=0)\n");
    return 2;
}
